#include "fates/graphics/auto_camera.hpp"
#include "fates/detail/principal_camera_runtime.hpp"
AutoCamera::AutoCamera()=default; AutoCamera::~AutoCamera(){fates::decomp_detail::AutoCameraDispose(*this);} void AutoCamera::ChangeToFocus(int id){focusUnit_=id;cutKind_=0;recalc_=true;ChangeCut();} void AutoCamera::ChangeToNormal(){if(focusUnit_!=-1){focusUnit_=-1;cutKind_=0;recalc_=true;ChangeCut();}} void AutoCamera::ChangeToWinCut(int id){focusUnit_=id;cutKind_=2;recalc_=true;ChangeCut();} void AutoCamera::ChangeToDeathCut(int id){focusUnit_=id;cutKind_=1;recalc_=true;ChangeCut();} void AutoCamera::ChangeCut(){recalc_=true;} void AutoCamera::Tick(){fates::decomp_detail::AutoCameraTick(*this);} void AutoCamera::Enter(){fates::decomp_detail::AutoCameraEnter(*this);} void AutoCamera::Leave(){} int AutoCamera::GetModeType()const{return 1;} bool AutoCamera::CanChangeMode()const{return true;} bool AutoCamera::CanLookAround()const{return true;} bool AutoCamera::IsHitPos()const{return true;} bool AutoCamera::IsHitArea()const{return true;} bool AutoCamera::IsHitFovy()const{return true;}
